import 'package:firebase_auth/firebase_auth.dart';
import 'package:flutter/material.dart';
import 'admin_dashboard_screen.dart';
class AdminLoginScreen extends StatefulWidget { const AdminLoginScreen({super.key}); @override State<AdminLoginScreen> createState()=>_AdminLoginScreenState(); }
class _AdminLoginScreenState extends State<AdminLoginScreen>{final email=TextEditingController(),password=TextEditingController();bool busy=false;Future<void> login()async{setState(()=>busy=true);try{final c=await FirebaseAuth.instance.signInWithEmailAndPassword(email:email.text.trim(),password:password.text);final token=await c.user!.getIdTokenResult(true);if(token.claims?['admin']!=true)throw Exception('Not admin');if(mounted)Navigator.pushReplacement(context,MaterialPageRoute(builder:(_)=>const AdminDashboardScreen()));}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Admin login failed')));}finally{if(mounted)setState(()=>busy=false);}}@override Widget build(BuildContext c)=>Scaffold(body:Center(child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:400),child:Padding(padding:const EdgeInsets.all(24),child:Column(mainAxisSize:MainAxisSize.min,children:[const Icon(Icons.admin_panel_settings,size:72,color:Colors.green),const SizedBox(height:16),const Text('FreshCart Admin',style:TextStyle(fontSize:26,fontWeight:FontWeight.bold)),const SizedBox(height:24),TextField(controller:email,decoration:const InputDecoration(labelText:'Email')),const SizedBox(height:12),TextField(controller:password,obscureText:true,decoration:const InputDecoration(labelText:'Password')),const SizedBox(height:20),SizedBox(width:double.infinity,child:FilledButton(onPressed:busy?null:login,child:Text(busy?'Signing in…':'Sign in')))]))));}
